 ri=np.arange(first,min(first+200000,len(cell)-1));ti=np.searchsorted(off,ri,side='right')-1;cur=cell[ri];nxt=cell[ri+1];ok=valid[ri]&(ri<off[ti+1]-1)&(cur<N)&(nxt<N);ri=ri[ok];ti=ti[ok];cur=cur[ok];nxt=nxt[ok];prev=cell[np.maximum(ri-1,0)];known=(ri>off[ti])&(prev<N)&valid[np.maximum(ri-1,0)];hh=np.where(known,heading(cur//ny-prev//ny,cur%ny-prev%ny),4);dx=nxt//ny-cur//ny;dy=nxt%ny-cur%ny;code=(dx+3)*7+dy+3;act=code-(code>24);assert np.all((act>=0)&(act<48));xy=np.column_stack([grid['x0']+(cur//ny+.5)*200,grid['y0']+(cur%ny+.5)*200]);rel=dest[ti]-xy;direction=(np.floor((np.arctan2(rel[:,1],rel[:,0])+math.pi/8)/(math.pi/4)).astype(np.int64)%8);distance=np.searchsorted([500,1500,4000],np.linalg.norm(rel,axis=1));group=((cur*8+direction)*4+distance)*5+hh;np.add.at(counts,(fold[ti],group,act),1);moves+=len(act)
